import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 수신 API이므로 방향은 항상 RECEIVE
const DIRECTION = 'RECEIVE';

@Controller('api/v1')
export class FnSir00201Controller {
  @Post('/integrations/internal-systems')
  @HttpCode(200)
  async receiveInternalSystemIntegration(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const data = checks.inputOf(req.body);
    const targetSystem = data['targetSystem'];
    const interfaceName = data['interfaceName'];
    const requestSummary = data['requestSummary'];
    if (typeof targetSystem !== 'string' || targetSystem.trim() === '' || targetSystem.length > 50) {
      throw new ApiError(422, 'INTEGRATION_REQUEST_INVALID', '연계 대상 시스템은 50자 이내로 필수 입력입니다.');
    }
    if (interfaceName !== undefined && interfaceName !== null && (typeof interfaceName !== 'string' || interfaceName.length > 100)) {
      throw new ApiError(422, 'INTEGRATION_REQUEST_INVALID', '인터페이스 이름은 100자 이내 문자열이어야 합니다.');
    }
    if (requestSummary !== undefined && requestSummary !== null && typeof requestSummary !== 'string') {
      throw new ApiError(422, 'INTEGRATION_REQUEST_INVALID', '연계 요청 데이터는 문자열이어야 합니다.');
    }
    return transaction(async (db) => {
      // 가정: 검증을 통과한 요청은 SUCCESS로 기록한다
      const rows = await db.query(
        `INSERT INTO integration_log
           (target_system, direction, interface_name, result_status, occurred_at, request_summary, created_at, updated_at)
         VALUES
           (:targetSystem, :direction, :interfaceName, 'SUCCESS', now(), :requestSummary, now(), now())
         RETURNING result_status AS "resultStatus", failure_reason AS "failureReason"`,
        {
          targetSystem: targetSystem.trim(),
          direction: DIRECTION,
          interfaceName: interfaceName ?? null,
          requestSummary: requestSummary ?? null,
        },
      );
      return rows[0];
    });
  }
}

