import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Form, Tiles, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSir00201Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [targetSystem, setTargetSystem] = useState('');
  const [interfaceName, setInterfaceName] = useState('');
  const [requestSummary, setRequestSummary] = useState('');

  const successCount = results.filter((r) => r.resultStatus === 'SUCCESS').length;
  const failureCount = results.filter((r) => r.resultStatus === 'FAILURE').length;

  const openDrawer = () => {
    setTargetSystem('');
    setInterfaceName('');
    setRequestSummary('');
    setOpen(true);
  };

  const submit = async () => {
    if (targetSystem.trim() === '') {
      throw new Error('연계 대상 시스템을 입력하세요.');
    }
    const res = await call('POST', '/integrations/internal-systems', role, {
      targetSystem: targetSystem.trim(),
      interfaceName,
      requestSummary,
    });
    setResults([
      {
        targetSystem: targetSystem.trim(),
        interfaceName,
        resultStatus: res.resultStatus,
        failureReason: res.failureReason,
      },
      ...results,
    ]);
    notify('연계 요청을 처리했습니다.');
    setOpen(false);
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['처리 건수', results.length],
            ['성공', successCount],
            ['실패', failureCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>연계 처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={openDrawer}>연계 요청</button>
        </Band>
        <DataTable
          columns={[
            { key: 'targetSystem', label: '연계 대상 시스템' },
            { key: 'interfaceName', label: '인터페이스 이름' },
            { key: 'resultStatus', label: '연계 결과', render: (r) => <Badge value={r.resultStatus} /> },
            { key: 'failureReason', label: '실패 사유' },
          ]}
          rows={results}
          empty="처리한 연계 요청이 없습니다."
        />
      </section>
      {open && (
        <Drawer title="연계 요청" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="요청 전달">
            <Field label="연계 대상 시스템" required>
              <TextInput value={targetSystem} onChange={setTargetSystem} />
            </Field>
            <Field label="인터페이스 이름">
              <TextInput value={interfaceName} onChange={setInterfaceName} />
            </Field>
            <Field label="연계 요청 데이터" wide>
              <TextInput value={requestSummary} onChange={setRequestSummary} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
